const j = $json;
let problems = j.problems || '';
if (!problems && j.error) problems = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
if (!problems && typeof j.text === 'string') problems = 'CV text could not be read (empty or too short)';
if (!problems) problems = 'Processing failed';
return { json: { 'CV File ID': $('Edit Fields1').first().json['CV File ID'], Status: 'Needs Review', Problems: problems } };

