// Mode: Run Once for Each Item

const ai = $json.output || {};

const errors = [];

// 1. Check score
if (
  typeof ai.score !== 'number' ||
  ai.score < 0 ||
  ai.score > 100
) {
  errors.push('Invalid score');
}

// 2. Check recommendation
const expected =
  ai.score >= 70 ? 'Interview' :
  ai.score >= 40 ? 'Maybe' :
  'Rejected';

if (ai.recommendation !== expected) {
  errors.push('Recommendation does not match score');
}

// 3. Check score breakdown
const total =
  Number(ai.skills_score) +
  Number(ai.experience_score) +
  Number(ai.education_score) +
  Number(ai.extras_score);

if (total !== ai.score) {
  errors.push('Score breakdown does not match total score');
}

// 4. Check reason
if (!ai.reason || String(ai.reason).trim().length < 10) {
  errors.push('Missing or invalid reason');
}

// Final result
const valid = errors.length === 0;

return {
  json: {
    ...$json,
    valid,
    problems: errors.join(' | '),
    problems_list: errors
  }
};
